/**
 * Branded Type Constructors
 *
 * Provides `create*` factory functions that wrap raw `Uint8Array` values into
 * their corresponding branded byte-array types after validating length constraints.
 *
 * For constructing branded types from raw `bigint` values, use the `assert*`
 * helpers exported from `common/types` or the `encode*` functions from
 * `byte-encoding`.
 *
 * @packageDocumentation
 * @module common/converters/branded
 * @since 2.0.0
 */

import {
  type Bytes,
  type U8LeBytes,
  type U8BeBytes,
  type U16LeBytes,
  type U16BeBytes,
  type U32LeBytes,
  type U32BeBytes,
  type U64LeBytes,
  type U64BeBytes,
  type U128LeBytes,
  type U128BeBytes,
  type U256LeBytes,
  type U256BeBytes,
  type U512LeBytes,
  type U512BeBytes,
  type U1024LeBytes,
  type U1024BeBytes,
  assertBytes,
  U8_BYTE_LENGTH,
  U16_BYTE_LENGTH,
  U32_BYTE_LENGTH,
  U64_BYTE_LENGTH,
  U128_BYTE_LENGTH,
  U256_BYTE_LENGTH,
  U512_BYTE_LENGTH,
  U1024_BYTE_LENGTH,
} from "../types";

import {
  type X25519PublicKey,
  type X25519PrivateKey,
  type X25519Bytes,
  type SharedSecret,
  assertX25519PublicKey,
  assertX25519PrivateKey,
  assertX25519Bytes,
  assertSharedSecret,
} from "../../types/cryptography";

import { assertByteLength } from "./errors";

/* =============================================================================
 * GENERIC BYTE ARRAY CONSTRUCTOR
 * ============================================================================= */

/**
 * Wraps a `Uint8Array` in the {@link Bytes} branded type.
 *
 * @param value - The raw `Uint8Array` to validate and brand.
 * @returns The same `Uint8Array`, branded as {@link Bytes}.
 * @throws {ConversionError} If `value` is not a `Uint8Array`.
 *
 * @since 2.0.0
 * @public
 */
export function createBytes(value: Uint8Array): Bytes {
  assertBytes(value);
  return value;
}

/* =============================================================================
 * LITTLE-ENDIAN BYTE ARRAY CONSTRUCTORS
 * ============================================================================= */

/**
 * Wraps a 1-byte `Uint8Array` in the {@link U8LeBytes} branded type.
 *
 * @param value - A `Uint8Array` of exactly 1 byte.
 * @returns The same `Uint8Array`, branded as {@link U8LeBytes}.
 * @throws {ConversionError} If not exactly 1 byte.
 *
 * @since 2.0.0
 * @public
 */
export function createU8LeBytes(value: Uint8Array): U8LeBytes {
  assertByteLength(value, U8_BYTE_LENGTH, "U8LeBytes");
  return value as U8LeBytes;
}

