/* =============================================================================
 * CRYPTOGRAPHIC BYTE ARRAY CONSTRUCTORS
 * ============================================================================= */

/**
 * Wraps a 32-byte `Uint8Array` in the {@link X25519Bytes} branded type.
 *
 * @param value - A `Uint8Array` of exactly 32 bytes.
 * @returns The same `Uint8Array`, branded as {@link X25519Bytes}.
 * @throws {CryptographyAssertionError} If not exactly 32 bytes.
 *
 * @since 2.0.0
 * @public
 */
export function createX25519Bytes(value: Uint8Array): X25519Bytes {
  assertX25519Bytes(value);
  return value;
}

/**
 * Wraps a 32-byte `Uint8Array` in the {@link X25519PublicKey} branded type.
 *
 * @param value - A `Uint8Array` of exactly 32 bytes representing an X25519 public key.
 * @returns The same `Uint8Array`, branded as {@link X25519PublicKey}.
 * @throws {CryptographyAssertionError} If not exactly 32 bytes.
 *
 * @since 2.0.0
 * @public
 */
export function createX25519PublicKey(value: Uint8Array): X25519PublicKey {
  assertX25519PublicKey(value);
  return value;
}

/**
 * Wraps a 32-byte `Uint8Array` in the {@link X25519PrivateKey} branded type.
 *
 * @remarks
 * **Security:** The caller is responsible for ensuring this value is treated as
 * secret material. Do not log, serialize, or transmit private keys.
 *
 * @param value - A `Uint8Array` of exactly 32 bytes representing an X25519 private key.
 * @returns The same `Uint8Array`, branded as {@link X25519PrivateKey}.
 * @throws {CryptographyAssertionError} If not exactly 32 bytes.
 *
 * @since 2.0.0
 * @public
 */
export function createX25519PrivateKey(value: Uint8Array): X25519PrivateKey {
  assertX25519PrivateKey(value);
  return value;
}

/**
 * Wraps a 32-byte `Uint8Array` in the {@link SharedSecret} branded type.
 *
 * @remarks
 * **Security:** Shared secrets are key material derived from ECDH.
 * Do not log or transmit.
 *
 * @param value - A `Uint8Array` of exactly 32 bytes.
 * @returns The same `Uint8Array`, branded as {@link SharedSecret}.
 * @throws {CryptographyAssertionError} If not exactly 32 bytes.
 *
 * @since 2.0.0
 * @public
 */
export function createSharedSecret(value: Uint8Array): SharedSecret {
  assertSharedSecret(value);
  return value;
}

