/**
 * Converter Error Classes
 *
 * Provides the {@link ConversionError} class thrown by all `convert*`, `create*`,
 * `encode*`, and `decode*` functions when a type transformation fails, along with
 * shared validation helpers used across all converter modules.
 *
 * @module common/converters/errors
 * @since 2.0.0
 */

import { UmbraError } from "../errors";

/* =============================================================================
 * CONVERSION ERROR
 * ============================================================================= */

/**
 * Error thrown when a type conversion fails.
 *
 * @remarks
 * Provides structured metadata about the failure: which value was being converted,
 * from which type, to which target type, and why it failed.
 *
 * ## When is this thrown?
 *
 * - **Narrowing conversions** (`convertU128ToU8`, etc.) — value exceeds target range.
 * - **Sign conversions** (`convertI64ToU64`, etc.) — negative to unsigned, or overflow.
 * - **Field element conversions** (`convertU256ToBn254FieldElement`, etc.) — value >= field prime.
 * - **Byte array constructors** (`createU128LeBytes`, etc.) — wrong length.
 * - **Number conversions** (`convertU64ToNumber`, etc.) — value exceeds `Number.MAX_SAFE_INTEGER`.
 *
 * @example
 * ```typescript
 * try {
 *   const narrow = convertU128ToU8(createU128(300n));
 * } catch (error) {
 *   if (error instanceof ConversionError) {
 *     console.error(`Cannot convert ${error.sourceType} to ${error.targetType}`);
 *     console.error(`Reason: ${error.reason}`);
 *   }
 * }
 * ```
 *
 * @since 2.0.0
 * @public
 */
export class ConversionError extends UmbraError {
  /** The original value that failed conversion. */
  public readonly sourceValue: unknown;

  /** The type name of the source value (e.g., `"bigint"`, `"number"`). */
  public readonly sourceType: string;

  /** The target branded type name (e.g., `"U8"`, `"Bn254FieldElement"`). */
  public readonly targetType: string;

  /**
   * Human-readable explanation of why the conversion failed.
   *
   * @remarks
   * Examples:
   * - `"Value 300 exceeds U8 maximum of 255"`
   * - `"Value exceeds BN254 field prime"`
   * - `"Cannot convert negative value -1 to unsigned type"`
   */
  public readonly reason: string;

  /**
   * @param message - A human-readable summary of the failure.
   * @param options - Structured metadata about the failed conversion.
   */
  constructor(
    message: string,
    options: {
      sourceValue: unknown;
      sourceType: string;
      targetType: string;
      reason: string;
    },
  ) {
    super(message, {
      code: `CONVERSION_${options.targetType.toUpperCase()}`,
    });
    this.name = "ConversionError";
    this.sourceValue = options.sourceValue;
    this.sourceType = options.sourceType;
    this.targetType = options.targetType;
    this.reason = options.reason;
  }
}

/**
 * Type guard to check if a value is a {@link ConversionError}.
 *
 * @param error - The value to test.
 * @returns `true` and narrows `error` to {@link ConversionError}.
 *
 * @since 2.0.0
 * @public
 */
export function isConversionError(error: unknown): error is ConversionError {
  return error instanceof ConversionError;
}

/* =============================================================================
 * SHARED VALIDATION HELPERS
 * ============================================================================= */

/**
 * Asserts that a bigint value is within the range `[min, max]` (inclusive).
 * Throws {@link ConversionError} if out of range.
 *
 * @param value - The value to check.
 * @param min - Minimum allowed value (inclusive).
 * @param max - Maximum allowed value (inclusive).
 * @param sourceType - Source type name for the error message.
 * @param targetType - Target type name for the error message.
 *
 * @throws {ConversionError} If value is outside the range.
 *
 * @internal
 */
export function assertBigintInRange(
  value: bigint,
  min: bigint,
  max: bigint,
  sourceType: string,
  targetType: string,
): void {
  if (value < min || value > max) {
    throw new ConversionError(
      `${sourceType} value ${String(value)} is out of range for ${targetType} [${String(min)}, ${String(max)}]`,
      {
        sourceValue: value,
        sourceType,
        targetType,
        reason: `Value must be in range [${String(min)}, ${String(max)}]`,
      },
    );
  }
}

/**
 * Asserts that a number value is a safe integer within the range `[min, max]`.
 * Throws {@link ConversionError} if not a safe integer or out of range.
 *
 * @param value - The value to check.
 * @param min - Minimum allowed value (inclusive).
 * @param max - Maximum allowed value (inclusive).
 * @param targetType - Target type name for the error message.
 *
 * @throws {ConversionError} If value is not a safe integer or outside the range.
 *
 * @internal
 */
export function assertNumberInRange(
  value: number,
  min: number,
  max: number,
  targetType: string,
): void {
  if (!Number.isSafeInteger(value)) {
    throw new ConversionError(
      `Value ${String(value)} is not a safe integer`,
      {
        sourceValue: value,
        sourceType: "number",
        targetType,
        reason: "Value must be a safe integer (Number.isSafeInteger)",
      },
    );
  }
  if (value < min || value > max) {
    throw new ConversionError(
      `number value ${String(value)} is out of range for ${targetType} [${String(min)}, ${String(max)}]`,
      {
        sourceValue: value,
        sourceType: "number",
        targetType,
        reason: `Value must be in range [${String(min)}, ${String(max)}]`,
      },
    );
  }
}

/**
 * Asserts that a Uint8Array has exactly the expected length.
 * Throws {@link ConversionError} if the length doesn't match.
 *
 * @param value - The byte array to check.
 * @param expectedLength - The required byte length.
 * @param targetType - Target type name for the error message.
 *
 * @throws {ConversionError} If value is not a Uint8Array or has wrong length.
 *
 * @internal
 */
export function assertByteLength(
  value: Uint8Array,
  expectedLength: number,
  targetType: string,
): void {
  if (!(value instanceof Uint8Array)) {
    throw new ConversionError(
      `Expected Uint8Array, got ${typeof value}`,
      {
        sourceValue: value,
        sourceType: typeof value,
        targetType,
        reason: "Input must be a Uint8Array",
      },
    );
  }
  if (value.length !== expectedLength) {
    throw new ConversionError(
      `Expected exactly ${String(expectedLength)} bytes, got ${String(value.length)}`,
      {
        sourceValue: value,
        sourceType: "Uint8Array",
        targetType,
        reason: `Length must be exactly ${String(expectedLength)} bytes`,
      },
    );
  }
}
